// ───────── Estimaciones (interno) ─────────
async function list() {
  const p = page('Estimaciones a contratistas', { sub: 'Una por obra, contratista y semana. La autorización congela cantidades, tarifas y sus fuentes.', actions: can('cestimates.prepare') ? btn('Nueva estimación', create, 'primary') : null });
  p.body.append(listView({ endpoint: '/api/c-estimates', panel: true, rowHref: (r) => `#/estimaciones-contratistas/${r.id}`, workFilter: true, emptyText: 'No hay estimaciones todavía.', views: [{ label: 'Todas', query: {} }, { label: 'En preparación', query: { 'f.status': 'borrador,revision_interna' } }, { label: 'Con el contratista', query: { 'f.status': 'revision_contratista,conciliacion' } }, { label: 'Por autorizar', query: { 'f.status': 'lista_autorizar' } }, { label: 'Por pagar', query: { 'f.payStatus': 'sin_pago,parcial', 'f.status': 'autorizada,cerrada' } }] }));
  return p.el;
}
async function create() {
  const o = await options(['works', 'contractors', 'periods']);
  const r = await formDialog({ title: 'Nueva estimación de contratista', fields: [{ key: 'workId', label: 'Obra', type: 'select', required: true, options: o.works }, { key: 'contractorId', label: 'Contratista', type: 'select', required: true, options: o.contractors }, { key: 'periodId', label: 'Semana', type: 'select', required: true, options: o.periods.filter((x) => x.status !== 'cerrada'), help: 'Las semanas cerradas admiten solo complementos.' }, { key: 'kind', label: 'Tipo', type: 'select', placeholder: false, options: [{ id: 'ordinaria', label: 'Ordinaria' }, { id: 'complementaria', label: 'Complementaria (requiere motivo)' }] }, { key: 'complementReason', label: 'Motivo del complemento', wide: true }], submit: (v) => post('/api/c-estimates', v) });
  if (r?.id) go(`#/estimaciones-contratistas/${r.id}`);
}
