  if (!portal && d.can?.priceException && i.method !== 'fijo' && !['autorizada', 'cerrada', 'cancelada'].includes(d.status)) actions.unshift({ label: 'Precio excepcional', run: async () => { setTimeout(async () => { if (await formDialog({ title: 'Precio excepcional', text: 'Requiere motivo; invalida la conformidad anterior de la partida.', fields: [{ key: 'unitPrice', label: 'Precio unitario', type: 'decimal', required: true }, { key: 'reason', label: 'Motivo', type: 'textarea', required: true }], submit: (v) => post(`/api/c-estimates/${d.id}/items/${i.id}/price`, v) })) reload(); }); } });
  if (portal && d.can?.respond && ['pendiente', 'observada'].includes(i.status)) actions.unshift({ label: 'Registrar observación', primary: true, run: async () => { setTimeout(() => observe(d, i, reload)); } });
