    const c = d.can; const T = (to, extra) => act(() => post(`/api/c-estimates/${id}/transition`, { to, recordVersion: d.recordVersion, ...extra })).then(reload);
    const actions = [chip(d.status, ST[d.status])];
    if (c.prepare && ['borrador', 'revision_interna'].includes(d.status)) actions.push(btn('Incorporar avances validados', async () => { const r = await formDialog({ title: 'Incorporar avances validados', text: 'Solo entra la ejecución que aún no está en otro documento de pago.', submitLabel: 'Incorporar', fields: [{ key: 'groupBy', label: 'Presentación', type: 'select', placeholder: false, options: [{ id: 'ubicacion', label: 'Una partida por ubicación y concepto' }, { id: 'concepto', label: 'Agrupar por concepto (conserva ubicaciones en el detalle)' }] }], submit: (v) => post(`/api/c-estimates/${id}/generate`, v) }); if (r) { toast(`${r.added} asignación(es) incorporadas${r.lateEntries ? `; ${r.lateEntries} de semanas anteriores (conservan su fecha real)` : ''}${r.pendingValuation ? `; ${r.pendingValuation} partida(s) sin tarifa` : ''}.`); reload(); } }));
    if (c.prepare && d.status === 'borrador') actions.push(btn('Enviar a revisión interna', () => T('revision_interna'), 'primary'));
    if (c.prepare && ['revision_interna', 'conciliacion'].includes(d.status)) actions.push(btn('Compartir con el contratista', () => T('revision_contratista'), d.status === 'revision_interna' ? 'primary' : ''));
    if (c.prepare && ['revision_contratista', 'conciliacion'].includes(d.status)) actions.push(btn('Registrar conformidad obtenida por otro medio', async () => { if (await formDialog({ title: 'Conformidad por otro medio', text: `Queda registrada como constancia operativa sobre la versión ${d.version}, con quién la recabó.`, fields: [{ key: 'signerName', label: 'Quién dio la conformidad', required: true }, { key: 'reason', label: 'Cómo se obtuvo (mensaje, firma en papel, llamada…)', type: 'textarea', required: true }], submit: (v) => post(`/api/c-estimates/${id}/external-conformity`, { ...v, version: d.version }) })) reload(); }));
