    if (c.prepare && ['borrador', 'revision_interna'].includes(d.status)) actions.push(btn('Cancelar', async () => { if (await withReason('Cancelar estimación', 'La ejecución incluida queda disponible de nuevo.', (v) => post(`/api/c-estimates/${id}/transition`, { to: 'cancelada', ...v }))) reload(); }, 'ghost'));
