    const excluded = d.items.filter((i) => ['rechazada', 'diferida'].includes(i.status));
    const stepIdx = { borrador: 0, revision_interna: 1, revision_contratista: 2, conciliacion: 2, lista_autorizar: 3, autorizada: 5, cerrada: d.obligation?.payStatus === 'pagado' ? 7 : 6, cancelada: 0 }[d.status];
